let currentInvitation = null;
const $ = (id) => document.getElementById(id);

function loadConfig(){
  try { return {...DEFAULT_CONFIG, ...JSON.parse(localStorage.getItem("speakerInviteConfig") || "{}")}; }
  catch { return {...DEFAULT_CONFIG}; }
}
function saveConfig(){
  const c = {
    congregationName:$("cfgName").value.trim(), congregationShort:$("cfgShort").value.trim(),
    address:$("cfgAddress").value.trim(), weekday:$("cfgWeekday").value.trim(),
    time:$("cfgTime").value.trim(), jwHub:$("cfgHub").value.trim(),
    latitude:$("cfgLat").value.trim(), longitude:$("cfgLng").value.trim(),
    contactName:$("cfgContact").value.trim(), contactPhone:$("cfgPhone").value.replace(/\D/g,""),
    whatsappMessage:$("cfgMessage").value.trim()
  };
  localStorage.setItem("speakerInviteConfig", JSON.stringify(c));
  showStatus("configStatus","Configurações salvas neste dispositivo.","ok");
}
function fillConfig(){
  const c=loadConfig();
  $("cfgName").value=c.congregationName;$("cfgShort").value=c.congregationShort;
  $("cfgAddress").value=c.address;$("cfgWeekday").value=c.weekday;$("cfgTime").value=c.time;
  $("cfgHub").value=c.jwHub;$("cfgLat").value=c.latitude;$("cfgLng").value=c.longitude;
  $("cfgContact").value=c.contactName;$("cfgPhone").value=c.contactPhone;$("cfgMessage").value=c.whatsappMessage;
}
function showStatus(id,msg,type="ok"){ const e=$(id);e.textContent=msg;e.className=`status show ${type}`; }
function clearStatus(id){ const e=$(id);e.textContent="";e.className="status"; }
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));}
function slug(s){return s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9]+/g,"_").replace(/^_|_$/g,"");}
function parseDate(value){
  if(!value) return null;
  let m=value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if(m) return new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));
  m=value.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);
  if(m) return new Date(Number(m[3]),Number(m[2])-1,Number(m[1]));
  return null;
}
function brDate(d){return new Intl.DateTimeFormat("pt-BR").format(d);}
function weekday(d){return new Intl.DateTimeFormat("pt-BR",{weekday:"long"}).format(d).replace(/^./,c=>c.toUpperCase());}
function calendarStamp(d,time){
  let h=19,m=0; const mt=String(time).match(/(\d{1,2})(?:[:h](\d{2}))?/i);
  if(mt){h=Number(mt[1]);m=Number(mt[2]||0);}
  const start=new Date(d.getFullYear(),d.getMonth(),d.getDate(),h,m);
  const end=new Date(start.getTime()+45*60*1000);
  const pad=n=>String(n).padStart(2,"0");
  const f=x=>`${x.getFullYear()}${pad(x.getMonth()+1)}${pad(x.getDate())}T${pad(x.getHours())}${pad(x.getMinutes())}00`;
  return [f(start),f(end),start,end];
}
function normalizeBrazilPhone(value){
  let digits=String(value||"").replace(/\D/g,"");
  if(digits.startsWith("00")) digits=digits.slice(2);
  if(digits.length===10 || digits.length===11) digits="55"+digits;
  if(!/^55\d{10,11}$/.test(digits)) throw new Error("Informe um telefone válido com DDD. Exemplo: (85) 99999-9999.");
  return digits;
}
function buildData(speaker,origin,dateValue,outlineNo,speakerPhone="",requireSpeakerPhone=false){
  const c=loadConfig(), d=parseDate(dateValue), no=Number(outlineNo), title=OUTLINES[no];
  if(!speaker||!origin||!d||!no) throw new Error("Preencha orador, congregação de origem, data e número do esboço.");
  if(!title) throw new Error(`O esboço ${outlineNo} não foi localizado na lista atualizada dos esboços.`);
  let speakerPhoneInternational="";
  if(speakerPhone) speakerPhoneInternational=normalizeBrazilPhone(speakerPhone);
  else if(requireSpeakerPhone) throw new Error("Informe o telefone/WhatsApp do orador.");
  const [startStamp,endStamp,start,end]=calendarStamp(d,c.time);
  const dateText=`${weekday(d)}, ${brDate(d)}`;
  const maps=`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(c.latitude+","+c.longitude)}`;
  const wa=`https://wa.me/55${c.contactPhone}?text=${encodeURIComponent(c.whatsappMessage)}`;
  const tel=`tel:+55${c.contactPhone}`;
  const details=`Orador: ${speaker}\nCongregação de origem: ${origin}\nTema: ${no} – "${title}"`;
  const gcal=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent("Discurso público – "+title)}&dates=${startStamp}/${endStamp}&details=${encodeURIComponent(details)}&location=${encodeURIComponent(c.address)}`;
  return {speaker,origin,speakerPhone:speakerPhoneInternational,d,no,title,c,dateText,maps,wa,tel,gcal,start,end};
}
function whatsappText(x){
return `*DISCURSO PÚBLICO CONGREGAÇÃO ${x.c.congregationShort.toUpperCase()}*

*Orador:* ${x.speaker}

*Congregação de origem:* ${x.origin}

*Tema do discurso:*
${x.no} – "${x.title}"

📅 *Data:* ${x.dateText}
🕖 *Horário:* ${x.c.time}

📍 *Congregação:* ${x.c.congregationName}
*Endereço:* ${x.c.address}.

*Acesse o convite completo neste arquivo.*
👇👇👇`;
}
function invitationHTML(x){
return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Convite – ${esc(x.speaker)}</title>
<style>:root{--a:#2f5d7c;--d:#244a63;--l:#d8e1e7;--s:#f5f8fa}*{box-sizing:border-box}body{margin:0;padding:22px 12px;font-family:Arial,Helvetica,sans-serif;background:linear-gradient(145deg,#eef3f7,#dfe8f0);color:#18232c}.card{max-width:640px;margin:auto;background:#fff;border-radius:24px;overflow:hidden;box-shadow:0 18px 45px rgba(25,45,60,.16)}header{padding:34px 24px 30px;text-align:center;color:#fff;background:linear-gradient(135deg,var(--d),var(--a))}header .i{font-size:38px}header h1{margin:9px 0 0}header p{margin:7px 0 0;opacity:.92}main{padding:26px 23px}.theme{padding:18px;border-left:5px solid var(--a);border-radius:14px;background:var(--s);margin-bottom:20px}.lab{font-size:12px;font-weight:700;text-transform:uppercase;color:#62717d}.num{margin-top:8px;color:var(--d);font-weight:700}.title{font-size:20px;font-weight:700;line-height:1.35;margin-top:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.info{padding:15px;border:1px solid var(--l);border-radius:14px}.full{grid-column:1/-1}.val{font-weight:700;line-height:1.45;margin-top:5px}.acts{display:grid;gap:11px;margin-top:21px}a.btn{display:block;padding:15px;border-radius:12px;text-align:center;text-decoration:none;font-weight:700}.pri{background:var(--a);color:white}.sec{border:1px solid var(--a);color:var(--d)}.contact{margin-top:23px;padding:19px;border:1px solid var(--l);border-radius:15px;background:var(--s)}.contact h2{margin:0;color:var(--d)}.contact p{line-height:1.5}.tw{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.wa{background:#1f8f4d;color:#fff}.call{background:#466a86;color:#fff}footer{margin-top:22px;padding:18px;text-align:center;background:var(--s);border-radius:14px;line-height:1.6;color:#46535f}@media(max-width:520px){body{padding:0;background:white}.card{min-height:100vh;border-radius:0}.grid,.tw{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class="card"><header><div class="i">📖</div><h1>Discurso Público</h1><p>Congregação ${esc(x.c.congregationShort)}</p></header><main><section class="theme"><div class="lab">Tema do discurso</div><div class="num">Esboço n.º ${x.no}</div><div class="title">“${esc(x.title)}”</div></section><section class="grid"><div class="info"><div class="lab">Orador</div><div class="val">👤 ${esc(x.speaker)}</div></div><div class="info"><div class="lab">Congregação de origem</div><div class="val">🏛️ ${esc(x.origin)}</div></div><div class="info"><div class="lab">Data</div><div class="val">📅 ${esc(x.dateText)}</div></div><div class="info"><div class="lab">Horário</div><div class="val">🕖 ${esc(x.c.time)}</div></div><div class="info full"><div class="lab">Endereço</div><div class="val">📍 ${esc(x.c.address)}</div></div></section><div class="acts"><a class="btn pri" href="${x.gcal}" target="_blank">📅 Adicionar ao Google Agenda</a><a class="btn sec" href="${x.maps}" target="_blank">🧭 Como chegar</a><a class="btn sec" href="${esc(x.c.jwHub)}" target="_blank">🔗 Abrir localização no JW Hub</a></div><section class="contact"><h2>📞 Precisa de ajuda?</h2><p>Em caso de necessidade ou se surgir algum imprevisto relacionado à sua designação, fique à vontade para entrar em contato.</p><strong>👤 ${esc(x.c.contactName)} — ${formatPhone(x.c.contactPhone)}</strong><div class="tw"><a class="btn wa" href="${x.wa}" target="_blank">WhatsApp</a><a class="btn call" href="${x.tel}">Ligar</a></div></section><footer>A Congregação ${esc(x.c.congregationShort)} agradece sua disposição.<br>Que o Senhor Jeová abençoe todos os arranjos para que você cumpra bem sua designação.</footer></main></div></body></html>`;
}
function formatPhone(p){ const s=String(p).replace(/\D/g,""); return s.length===11?`(${s.slice(0,2)}) ${s.slice(2,7)}-${s.slice(7)}`:s; }
function icsText(x){
  const pad=n=>String(n).padStart(2,"0"), utc=d=>`${d.getUTCFullYear()}${pad(d.getUTCMonth()+1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}00Z`;
  const clean=s=>String(s).replace(/\\/g,"\\\\").replace(/\n/g,"\\n").replace(/,/g,"\\,").replace(/;/g,"\\;");
  return `BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Convite de Oradores//PT-BR\r\nCALSCALE:GREGORIAN\r\nBEGIN:VEVENT\r\nUID:${Date.now()}-${x.no}@convite-oradores\r\nDTSTAMP:${utc(new Date())}\r\nDTSTART:${utc(x.start)}\r\nDTEND:${utc(x.end)}\r\nSUMMARY:${clean("Discurso público – "+x.title)}\r\nDESCRIPTION:${clean("Orador: "+x.speaker+"\nCongregação de origem: "+x.origin+"\nEsboço "+x.no+" – "+x.title)}\r\nLOCATION:${clean(x.c.address)}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;
}
function downloadBlob(name,content,type="text/plain;charset=utf-8"){ const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000); }
function generateSingle(){
  clearStatus("singleStatus");
  try{
    const x=buildData($("speaker").value.trim(),$("origin").value.trim(),$("date").value,$("outline").value,$("speakerPhone").value.trim(),true);
    currentInvitation=x;
    $("waOutput").textContent=whatsappText(x);
    $("previewFrame").srcdoc=invitationHTML(x);
    $("singleOutput").hidden=false;
    showStatus("singleStatus","Convite gerado e conferido com a lista atualizada dos esboços.","ok");
  }catch(e){ $("singleOutput").hidden=true;showStatus("singleStatus",e.message,"error"); }
}
function buildWhatsAppUrl(phone, message){
  const validPhone=normalizeBrazilPhone(phone);
  const cleanMessage=String(message||"")
    .replace(/\r\n?/g,"\n")
    .normalize("NFC");
  return `https://api.whatsapp.com/send?phone=${encodeURIComponent(validPhone)}&text=${encodeURIComponent(cleanMessage)}`;
}
function invitationHtmlFilename(x){
  const safeName=String(x.speaker||"Orador")
    .normalize("NFC")
    .replace(/[\\/:*?"<>|]/g,"")
    .replace(/\s+/g," ")
    .trim() || "Orador";
  const date=brDate(x.d).replaceAll("/","-");
  return `Convite - ${safeName} - ${date}.html`;
}
function saveInvitationHTML(x){
  downloadBlob(invitationHtmlFilename(x),invitationHTML(x),"text/html;charset=utf-8");
}
function sendWhatsApp(){
  if(!currentInvitation){
    showStatus("singleStatus","Gere o convite antes de enviar a mensagem.","error");
    return;
  }
  try{
    const url=buildWhatsAppUrl(currentInvitation.speakerPhone,whatsappText(currentInvitation));

    // Salva primeiro o convite HTML. Assim, ele fica entre os arquivos mais
    // recentes para ser anexado manualmente na conversa do WhatsApp.
    saveInvitationHTML(currentInvitation);

    const link=document.createElement("a");
    link.href=url;
    link.target="_blank";
    link.rel="noopener noreferrer";
    document.body.appendChild(link);
    link.click();
    link.remove();
    showStatus("singleStatus",`O convite ${invitationHtmlFilename(currentInvitation)} foi salvo e o WhatsApp foi aberto com a mensagem pronta. Anexe o arquivo recém-baixado e toque em Enviar.`,"ok");
  }catch(e){
    showStatus("singleStatus",e.message||"Não foi possível preparar o convite para o WhatsApp.","error");
  }
}

async function copyWhatsApp(){
  if(!currentInvitation) return;
  const text = whatsappText(currentInvitation);

  // Método moderno: funciona em contextos seguros (HTTPS/localhost).
  if (navigator.clipboard && window.isSecureContext) {
    try {
      await navigator.clipboard.writeText(text);
      showStatus("singleStatus","Mensagem copiada.","ok");
      return;
    } catch (e) {
      // Se falhar, segue para o método alternativo abaixo.
    }
  }

  // Método alternativo para Android/Chrome e arquivos abertos diretamente.
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.opacity = "0";
  area.style.left = "-9999px";
  area.style.top = "0";
  document.body.appendChild(area);
  area.focus();
  area.select();
  area.setSelectionRange(0, area.value.length);

  let copied = false;
  try {
    copied = document.execCommand("copy");
  } catch (e) {
    copied = false;
  }
  document.body.removeChild(area);

  if (copied) {
    showStatus("singleStatus","Mensagem copiada.","ok");
  } else {
    // Último recurso: seleciona o texto visível para facilitar a cópia manual.
    const output = $("waOutput");
    const range = document.createRange();
    range.selectNodeContents(output);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
    showStatus("singleStatus","O navegador não permitiu copiar automaticamente. O texto foi selecionado; toque e segure para copiar.","error");
  }
}
